package protocol

import (
	"context"
	"errors"
	"reflect"
	"slices"

	"github.com/DataDog/datadog-agent/pkg/logs/internal/smb/thirdparty/gosmb2/internal/erref"
	"github.com/DataDog/datadog-agent/pkg/logs/internal/smb/thirdparty/gosmb2/x/wire"
)

// DirectReadRequest asks the transport to place the READ response payload
// directly into Buffer. Buffer must remain available and unmodified until
// Do or Receive returns; ownership remains with the caller.
type DirectReadRequest struct {
	*wire.ReadRequest
	Buffer []byte
}

// Request builds a related group of SMB operations on one tree. Operations
// after the first inherit the preceding operation's file handle, including a
// handle generated by CREATE. Use separate requests for independent handles.
// From Send until Receive returns, the Request, its packets, and borrowed
// buffers must not be modified. Request stores construction options only;
// PendingRequest owns execution state.
// The zero value cannot send requests; obtain one from Tree.Request.
type Request struct {
	tc             *Tree
	fd             wire.FileId
	pkts           []wire.Packet
	followSymlinks bool
	appendErr      error
}

// Request starts a request with symbolic-link following disabled.
func (tc *Tree) Request() *Request {
	return &Request{tc: tc}
}

// WithFileID sets the file handle and returns req. It modifies req in place.
func (req *Request) WithFileID(fd wire.FileId) *Request {
	if req == nil {
		return nil
	}
	req.fd = fd
	return req
}

// WithFollowSymlinks controls whether a leading CREATE is retried after
// STATUS_STOPPED_ON_SYMLINK by resolving the link target. It is disabled by default.
//
// The CREATE options still control whether the final path component is followed:
// FILE_OPEN_REPARSE_POINT opens the final link itself, even when follow is true.
// Links in intermediate path components can still be followed.
//
// WithFollowSymlinks modifies req in place and returns it.
func (req *Request) WithFollowSymlinks(follow bool) *Request {
	if req == nil {
		return nil
	}
	req.followSymlinks = follow
	return req
}

func (req *Request) Append(pkts ...wire.Packet) *Request {
	if req == nil {
		return nil
	}
	for _, pkt := range pkts {
		if pkt == nil {
			req.appendErr = errors.New("protocol: nil packet")
			continue
		}
		v := reflect.ValueOf(pkt)
		if v.Kind() == reflect.Pointer && v.IsNil() {
			req.appendErr = errors.New("protocol: nil packet")
			continue
		}
		if read, ok := pkt.(*DirectReadRequest); ok && read.ReadRequest == nil {
			req.appendErr = errors.New("protocol: nil direct read request")
			continue
		}
		req.pkts = append(req.pkts, pkt)
	}
	return req
}

func (req *Request) Get(i int) wire.Packet {
	if req == nil || i < 0 || i >= len(req.pkts) {
		return nil
	}
	return req.pkts[i]
}

// Create appends a CREATE request with optional SMB create contexts.
//
// Datadog patch: the default ShareAccess also includes FILE_SHARE_DELETE so
// that an open held by this client never makes another client's rename or
// delete of the same file fail with STATUS_SHARING_VIOLATION (the [MS-FSA]
// share-access check). The oplock level stays NONE and no lease or
// durable-handle create context is added here.
func (req *Request) Create(name string, access, disposition, options, attrs uint32, contexts ...wire.Encoder) *Request {
	if req == nil {
		return nil
	}
	p := &wire.CreateRequest{
		SecurityFlags:        0,
		RequestedOplockLevel: wire.SMB2_OPLOCK_LEVEL_NONE,
		ImpersonationLevel:   wire.Impersonation,
		SmbCreateFlags:       0,
		DesiredAccess:        access,
		FileAttributes:       attrs,
		ShareAccess:          wire.FILE_SHARE_READ | wire.FILE_SHARE_WRITE | wire.FILE_SHARE_DELETE,
		CreateDisposition:    disposition,
		CreateOptions:        options,
		Name:                 name,
		Contexts:             contexts,
	}
	req.Append(p)
	req.fd = wire.RelatedFileId
	return req
}

func (req *Request) Close() *Request {
	if req == nil {
		return nil
	}
	p := &wire.CloseRequest{
		Flags:  0,
		FileId: req.fd,
	}
	return req.Append(p)
}

func (req *Request) Flush() *Request {
	if req == nil {
		return nil
	}
	p := &wire.FlushRequest{
		FileId: req.fd,
	}
	return req.Append(p)
}

func (req *Request) SetInfo(infoType, infoClass uint8, additionalInfo uint32, input wire.Encoder) *Request {
	if req == nil {
		return nil
	}
	p := &wire.SetInfoRequest{
		InfoType:              infoType,
		FileInfoClass:         infoClass,
		AdditionalInformation: additionalInfo,
		FileId:                req.fd,
		Input:                 input,
	}
	return req.Append(p)
}

func (req *Request) QueryInfo(infoType, infoClass uint8, additionalInfo, bufferLen uint32) *Request {
	if req == nil {
		return nil
	}
	p := &wire.QueryInfoRequest{
		InfoType:              infoType,
		FileInfoClass:         infoClass,
		AdditionalInformation: additionalInfo,
		Flags:                 0,
		OutputBufferLength:    bufferLen,
		FileId:                req.fd,
	}
	return req.Append(p)
}

func (req *Request) Ioctl(ctlCode uint32, input wire.Encoder, maxOutput uint32) *Request {
	if req == nil {
		return nil
	}
	p := &wire.IoctlRequest{
		CtlCode:           ctlCode,
		OutputOffset:      0,
		OutputCount:       0,
		MaxInputResponse:  0,
		MaxOutputResponse: maxOutput,
		Flags:             wire.SMB2_0_IOCTL_IS_FSCTL,
		Input:             input,
		FileId:            req.fd,
	}
	return req.Append(p)
}

func (req *Request) QueryDir(infoClass uint8, pattern string, bufferLen uint32) *Request {
	if req == nil {
		return nil
	}
	p := &wire.QueryDirectoryRequest{
		FileInfoClass:      infoClass,
		Flags:              0,
		FileIndex:          0,
		FileId:             req.fd,
		FileName:           pattern,
		OutputBufferLength: bufferLen,
	}
	return req.Append(p)
}

func (req *Request) Read(length uint32, offset uint64) *Request {
	if req == nil {
		return nil
	}
	p := &wire.ReadRequest{
		Padding:      0,
		Flags:        0,
		Length:       length,
		Offset:       offset,
		FileId:       req.fd,
		MinimumCount: 0,
	}
	return req.Append(p)
}

func (req *Request) Write(data []byte, offset uint64) *Request {
	if req == nil {
		return nil
	}
	p := &wire.WriteRequest{
		Offset: offset,
		Flags:  0,
		FileId: req.fd,
		Data:   data,
	}
	return req.Append(p)
}

func (req *Request) ChangeNotify(filter uint32, recursive bool, outputBufferLength uint32) *Request {
	if req == nil {
		return nil
	}
	flags := uint16(0)
	if recursive {
		flags = wire.SMB2_WATCH_TREE
	}
	return req.Append(&wire.ChangeNotifyRequest{
		Flags:              flags,
		OutputBufferLength: outputBufferLength,
		FileId:             req.fd,
		CompletionFilter:   filter,
	})
}

func (req *Request) Lock(locks []wire.LockElement) *Request {
	if req == nil {
		return nil
	}
	return req.Append(&wire.LockRequest{
		FileId: req.fd,
		Locks:  locks,
	})
}

// Do sends the request and waits for all responses. On failure it reclaims
// only handles created by this request, and returns no response. On success the
// caller owns any handles left open and must Close the response buffers.
func (req *Request) Do(ctx context.Context) (*Response, error) {
	if ctx == nil {
		panic("nil context")
	}
	pending, err := req.Send(ctx)
	if err != nil {
		return nil, err
	}
	return pending.Receive()
}

// PendingRequest is the receive half of a request sent with Send. Receive must
// be called exactly once, including after cancellation, to finish reception and
// release any buffers borrowed from the caller. It is not safe for concurrent use.
type PendingRequest struct {
	req  *Request
	rrs  []*outstandingRequest
	ctx  context.Context
	done bool
}

// Send starts the request. The caller must call Receive on a successful result,
// then Close its response. If the credit window cannot accommodate the entire
// compound, Receive sends its operations sequentially. WithFollowSymlinks applies
// when Receive processes the responses.
func (req *Request) Send(ctx context.Context) (*PendingRequest, error) {
	if ctx == nil {
		panic("nil context")
	}
	if req == nil || req.tc == nil || req.tc.session == nil || req.tc.conn == nil {
		return nil, errors.New("protocol: nil request")
	}
	if req.appendErr != nil {
		return nil, req.appendErr
	}
	if len(req.pkts) == 0 {
		return nil, errors.New("protocol: empty compound request")
	}
	rrs, err := req.tc.send(ctx, req.pkts...)
	if err != nil && err != errCompoundCredits {
		return nil, err
	}
	if hasCreateRequest(req.pkts) {
		for _, rr := range rrs {
			rr.waitFinal = true
		}
	}
	return &PendingRequest{req: req, rrs: rrs, ctx: ctx}, nil
}

// Receive waits for all responses. It has the same ownership and error contract
// as Do, including handle recovery and optional symbolic-link following.
func (p *PendingRequest) Receive() (*Response, error) {
	if p == nil || p.done || p.req == nil || p.ctx == nil {
		return nil, errors.New("protocol: request already received or not sent")
	}
	p.done = true
	pending := p
	for attempt := 0; ; attempt++ {
		res, err := pending.receiveOnce()
		if err == nil {
			if create, ok := pending.req.pkts[0].(*wire.CreateRequest); ok {
				res.resolvedPath = create.Name
			}
			return res, nil
		}
		req := pending.req
		create, isCreate := req.pkts[0].(*wire.CreateRequest)
		stopped := responseErrorAt(err, 0)
		if !req.followSymlinks || !isCreate || stopped == nil ||
			erref.NtStatus(stopped.Code) != erref.STATUS_STOPPED_ON_SYMLINK ||
			!continuationSafe(err, req.pkts) {
			return nil, req.referralError(err)
		}
		var linkData []byte
		if len(stopped.data) > 0 {
			linkData = stopped.data[0]
		}
		name, err := req.resolveSymlink(p.ctx, create.Name, stopped, linkData)
		if err != nil {
			return nil, err
		}
		if attempt+1 >= clientMaxSymlinkDepth {
			return nil, errors.New("protocol: Too many levels of symbolic links")
		}
		retry := *req
		retry.pkts = slices.Clone(req.pkts)
		retryCreate := *create
		retryCreate.Name = name
		retry.pkts[0] = &retryCreate
		pending, err = retry.Send(p.ctx)
		if err != nil {
			return nil, err
		}
	}
}

func (p *PendingRequest) receiveOnce() (*Response, error) {
	var res *Response
	var err error
	if p.rrs == nil {
		res, err = p.req.tc.sendRecvSequential(p.ctx, p.req.pkts)
	} else {
		res, err = recvAll(p.rrs, p.req.tc)
	}
	if hasCreateRequest(p.req.pkts) && p.ctx.Err() != nil {
		err = p.ctx.Err()
	}
	if err != nil {
		p.req.tc.closeResponseFile(p.req.pkts, res)
		res.close()
		return nil, err
	}
	return res, nil
}

func (req *Request) referralError(err error) error {
	if req.tc.isDFSShare {
		if stopped := responseErrorAt(err, 0); stopped != nil &&
			erref.NtStatus(stopped.Code) == erref.STATUS_PATH_NOT_COVERED && continuationSafe(err, req.pkts) {
			if create, ok := req.pkts[0].(*wire.CreateRequest); ok {
				return &DFSReferralRequiredError{
					Path:         req.tc.uncPath(create.Name),
					ReparsePoint: create.CreateOptions&wire.FILE_OPEN_REPARSE_POINT != 0,
					err:          stopped,
				}
			}
		}
	}
	return err
}

// continuationSafe checks that responses indicate later operations were skipped
// after CREATE stopped with STATUS_STOPPED_ON_SYMLINK or STATUS_PATH_NOT_COVERED.
// [MS-SMB2] 3.3.5.2.7.2 requires related operations to execute in order and
// fail with STATUS_INVALID_HANDLE for a missing FileId or
// STATUS_INVALID_PARAMETER for a missing SessionId or TreeId. When a FileId
// is available, the server SHOULD propagate the previous operation's error.
// macOS reports STATUS_FILE_CLOSED for the unavailable related handle.
// Accept these unavailable-handle/identifier errors or the same stopped status;
// success, non-response errors, and unrelated failures prevent continuation.
// This checks reported outcomes, not actual side effects on a hostile server.
func continuationSafe(err error, reqs []wire.Packet) bool {
	if len(reqs) == 0 {
		return false
	}
	first := responseErrorAt(err, 0)
	if first == nil {
		return false
	}
	firstStatus := erref.NtStatus(first.Code)
	if firstStatus != erref.STATUS_STOPPED_ON_SYMLINK && firstStatus != erref.STATUS_PATH_NOT_COVERED {
		return false
	}
	if len(reqs) == 1 {
		return true
	}
	ce, ok := errors.AsType[*CompoundResponseError](err)
	if !ok || len(ce.Errors) != len(reqs) {
		return false
	}
	for _, e := range ce.Errors[1:] {
		if e == nil {
			return false
		}
		rerr, ok := errors.AsType[*ResponseError](e)
		if !ok {
			return false
		}
		switch erref.NtStatus(rerr.Code) {
		case erref.STATUS_INVALID_HANDLE, erref.STATUS_FILE_CLOSED, erref.STATUS_INVALID_PARAMETER, firstStatus:
		default:
			return false
		}
	}
	return true
}

func responseErrorAt(err error, index int) *ResponseError {
	if ce, ok := errors.AsType[*CompoundResponseError](err); ok {
		err = ce.OpError(index)
	} else if index != 0 {
		return nil
	}
	if rerr, ok := errors.AsType[*ResponseError](err); ok {
		return rerr
	}
	return nil
}
